COMMENT ON TABLE "detention_arrival_daily" IS 'keel rollup detention_arrival_daily of detention_occurrences';
ALTER TABLE "detention_arrival_daily" ALTER COLUMN "business_unit_id" SET NOT NULL, ALTER COLUMN "organization_id" SET NOT NULL;
CREATE UNIQUE INDEX "detention_arrival_daily_key" ON "detention_arrival_daily" ("business_unit_id", "organization_id", "bucket") NULLS NOT DISTINCT;
CREATE OR REPLACE FUNCTION keel_rollup_detention_arrival_daily() RETURNS trigger LANGUAGE plpgsql AS $keel$
BEGIN
    IF TG_OP = 'INSERT' THEN
        INSERT INTO keel_rollup_dirty (rollup, tenant_key, bucket, xid)
        SELECT DISTINCT 'detention_arrival_daily', replace(replace(coalesce(n."business_unit_id"::text, ''), '\', '\\'), '/', '\/') || '/' || replace(replace(coalesce(n."organization_id"::text, ''), '\', '\\'), '/', '\/'), coalesce(date_trunc('day', to_timestamp(n."arrived_at"), (coalesce((SELECT z."timezone" FROM "organizations" z WHERE z."id" = n."organization_id"), 'UTC'))), 'infinity'), pg_current_xact_id()
          FROM keel_new n
        ON CONFLICT DO NOTHING;
    ELSIF TG_OP = 'DELETE' THEN
        INSERT INTO keel_rollup_dirty (rollup, tenant_key, bucket, xid)
        SELECT DISTINCT 'detention_arrival_daily', replace(replace(coalesce(n."business_unit_id"::text, ''), '\', '\\'), '/', '\/') || '/' || replace(replace(coalesce(n."organization_id"::text, ''), '\', '\\'), '/', '\/'), coalesce(date_trunc('day', to_timestamp(n."arrived_at"), (coalesce((SELECT z."timezone" FROM "organizations" z WHERE z."id" = n."organization_id"), 'UTC'))), 'infinity'), pg_current_xact_id()
          FROM keel_old n
        ON CONFLICT DO NOTHING;
    ELSE
        INSERT INTO keel_rollup_dirty (rollup, tenant_key, bucket, xid)
        SELECT DISTINCT 'detention_arrival_daily', replace(replace(coalesce(n."business_unit_id"::text, ''), '\', '\\'), '/', '\/') || '/' || replace(replace(coalesce(n."organization_id"::text, ''), '\', '\\'), '/', '\/'), coalesce(date_trunc('day', to_timestamp(n."arrived_at"), (coalesce((SELECT z."timezone" FROM "organizations" z WHERE z."id" = n."organization_id"), 'UTC'))), 'infinity'), pg_current_xact_id()
          FROM ((SELECT "business_unit_id", "organization_id", "arrived_at", "is_open", "free_minutes_granted", "raw_dwell_minutes" FROM keel_old EXCEPT ALL SELECT "business_unit_id", "organization_id", "arrived_at", "is_open", "free_minutes_granted", "raw_dwell_minutes" FROM keel_new) UNION ALL (SELECT "business_unit_id", "organization_id", "arrived_at", "is_open", "free_minutes_granted", "raw_dwell_minutes" FROM keel_new EXCEPT ALL SELECT "business_unit_id", "organization_id", "arrived_at", "is_open", "free_minutes_granted", "raw_dwell_minutes" FROM keel_old)) n
        ON CONFLICT DO NOTHING;
    END IF;
    RETURN NULL;
END
$keel$;
CREATE OR REPLACE TRIGGER "keel_rollup_detention_arrival_daily_insert" AFTER INSERT ON "detention_occurrences" REFERENCING NEW TABLE AS keel_new FOR EACH STATEMENT EXECUTE FUNCTION keel_rollup_detention_arrival_daily();
CREATE OR REPLACE TRIGGER "keel_rollup_detention_arrival_daily_update" AFTER UPDATE ON "detention_occurrences" REFERENCING OLD TABLE AS keel_old NEW TABLE AS keel_new FOR EACH STATEMENT EXECUTE FUNCTION keel_rollup_detention_arrival_daily();
CREATE OR REPLACE TRIGGER "keel_rollup_detention_arrival_daily_delete" AFTER DELETE ON "detention_occurrences" REFERENCING OLD TABLE AS keel_old FOR EACH STATEMENT EXECUTE FUNCTION keel_rollup_detention_arrival_daily();
--keel:split
WITH marked AS (INSERT INTO keel_rollup_dirty (rollup, tenant_key, bucket, xid) SELECT DISTINCT 'detention_arrival_daily', replace(replace(coalesce(s."business_unit_id"::text, ''), '\', '\\'), '/', '\/') || '/' || replace(replace(coalesce(s."organization_id"::text, ''), '\', '\\'), '/', '\/'), '-infinity'::timestamptz, pg_current_xact_id() FROM "detention_occurrences" s ON CONFLICT DO NOTHING)
INSERT INTO keel_rollup_state (rollup, ready_at) VALUES ('detention_arrival_daily', now()) ON CONFLICT (rollup) DO UPDATE SET ready_at = excluded.ready_at;
